import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-clever-calc-1.svg",x=JSON.parse('{"title":"奥数入门：速算与巧算（一）凑整法的奥秘","description":"计算是数学的基础，而巧算则是数学的艺术。本文带你掌握奥数中最基础也最强大的武器——凑整法，让复杂的加减法瞬间变简单。","frontmatter":{"title":"奥数入门：速算与巧算（一）凑整法的奥秘","date":"2026-02-11T09:00:00.000Z","categories":["数学"],"tags":["小学奥数","计算技巧","凑整法","速算"],"description":"计算是数学的基础，而巧算则是数学的艺术。本文带你掌握奥数中最基础也最强大的武器——凑整法，让复杂的加减法瞬间变简单。","cover":"/img/math-clever-calc-1.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-calc-1.md","filePath":"posts/primary-math-olympiad-calc-1.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-calc-1.md"};function r(o,a,e,c,i,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="奥数入门-速算与巧算-一-凑整法的奥秘" tabindex="-1">奥数入门：速算与巧算（一）凑整法的奥秘 <a class="header-anchor" href="#奥数入门-速算与巧算-一-凑整法的奥秘" aria-label="Permalink to &quot;奥数入门：速算与巧算（一）凑整法的奥秘&quot;">​</a></h1><p>在数学竞赛中，我们经常会看到一些长长的加减法算式。如果老老实实从左往右算，不仅慢，还容易出错。</p><p>其实，数字之间也是有“好朋友”的。只要找准了这些好朋友，算式就会像变魔术一样变简单。这就是我们今天要学习的<strong>速算与巧算核心技巧：凑整法</strong>。</p><hr><h2 id="一、-什么是-凑整法" tabindex="-1">一、 什么是“凑整法”？ <a class="header-anchor" href="#一、-什么是-凑整法" aria-label="Permalink to &quot;一、 什么是“凑整法”？&quot;">​</a></h2><p>凑整法，顾名思义，就是把算式中的某些数通过交换、结合，凑成整十、整百、整千的数。</p><p><strong>为什么要凑整？</strong> 因为整十、整百的数加减起来最快，不容易出错。</p><p><img src="'+p+'" alt="凑整法示意图"></p><hr><h2 id="二、-核心秘诀-找准-好朋友" tabindex="-1">二、 核心秘诀：找准“好朋友” <a class="header-anchor" href="#二、-核心秘诀-找准-好朋友" aria-label="Permalink to &quot;二、 核心秘诀：找准“好朋友”&quot;">​</a></h2><p>要想凑整，首先要记住哪些数字相加能得到 10、100。</p><h3 id="_1-凑十好朋友-个位数相加" tabindex="-1">1. 凑十好朋友（个位数相加） <a class="header-anchor" href="#_1-凑十好朋友-个位数相加" aria-label="Permalink to &quot;1. 凑十好朋友（个位数相加）&quot;">​</a></h3><ul><li>1 和 9</li><li>2 和 8</li><li>3 和 7</li><li>4 和 6</li><li>5 和 5</li></ul><h3 id="_2-凑百好朋友" tabindex="-1">2. 凑百好朋友 <a class="header-anchor" href="#_2-凑百好朋友" aria-label="Permalink to &quot;2. 凑百好朋友&quot;">​</a></h3><ul><li>11 和 89</li><li>25 和 75</li><li>36 和 64</li><li>50 和 50</li></ul><hr><h2 id="三、-实战技巧解析" tabindex="-1">三、 实战技巧解析 <a class="header-anchor" href="#三、-实战技巧解析" aria-label="Permalink to &quot;三、 实战技巧解析&quot;">​</a></h2><h3 id="技巧-1-交换位置找朋友" tabindex="-1">技巧 1：交换位置找朋友 <a class="header-anchor" href="#技巧-1-交换位置找朋友" aria-label="Permalink to &quot;技巧 1：交换位置找朋友&quot;">​</a></h3><p>当一连串数字相加时，我们可以先跳着加那些能凑整的数。</p><p><strong>【例题 1】</strong> 计算：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>7</mn><mo>+</mo><mn>3</mn><mn>6</mn><mo>+</mo><mn>7</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">27 + 36 + 73</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span></span></span></span><strong>解析</strong>： 观察个位，7 和 3 是好朋友。 我们可以先算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>7</mn><mo>+</mo><mn>7</mn><mn>3</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">27 + 73 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。 再算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>3</mn><mn>6</mn><mo>=</mo><mn>1</mn><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">100 + 36 = 136</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>。 <strong>答案</strong>：136。</p><h3 id="技巧-2-拆分补偿法" tabindex="-1">技巧 2：拆分补偿法 <a class="header-anchor" href="#技巧-2-拆分补偿法" aria-label="Permalink to &quot;技巧 2：拆分补偿法&quot;">​</a></h3><p>如果某个数接近整十、整百，我们可以先把它当成整十整百来算，多算了再减掉，少算了再补上。</p><p><strong>【例题 2】</strong> 计算：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>8</mn><mo>+</mo><mn>4</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">98 + 45</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span></span></span></span><strong>解析</strong>： 98 离 100 很近，我们可以把它看成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">100 - 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span></span></span></span>。 算式变成：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>2</mn><mo>)</mo><mo>+</mo><mn>4</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>4</mn><mn>5</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>4</mn><mn>5</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>4</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">(100 - 2) + 45 = 100 + 45 - 2 = 145 - 2 = 143</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span></span></span></span>。 <strong>答案</strong>：143。</p><hr><h2 id="四、-避坑指南-看清符号" tabindex="-1">四、 避坑指南：看清符号 <a class="header-anchor" href="#四、-避坑指南-看清符号" aria-label="Permalink to &quot;四、 避坑指南：看清符号&quot;">​</a></h2><p>在交换数字位置时，一定要<strong>带着数字前面的符号一起走</strong>。</p><ul><li>例：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>3</mn><mo>−</mo><mn>4</mn><mn>5</mn><mo>+</mo><mn>7</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">123 - 45 + 77</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">7</span></span></span></span></li><li>我们可以换成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>3</mn><mo>+</mo><mn>7</mn><mn>7</mn><mo>−</mo><mn>4</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">123 + 77 - 45</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">7</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span></span></span></span>。</li><li>但千万不能换成 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>3</mn><mo>−</mo><mo>(</mo><mn>4</mn><mn>5</mn><mo>+</mo><mn>7</mn><mn>7</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">123 - (45 + 77)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">7</span><span class="mclose">)</span></span></span></span>，那是完全不同的结果哦！</li></ul><hr><h2 id="五、-练一练-挑战速算王" tabindex="-1">五、 练一练（挑战速算王） <a class="header-anchor" href="#五、-练一练-挑战速算王" aria-label="Permalink to &quot;五、 练一练（挑战速算王）&quot;">​</a></h2><ol><li><strong>基础题</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>+</mo><mn>2</mn><mn>8</mn><mo>+</mo><mn>8</mn><mn>5</mn><mo>+</mo><mn>7</mn><mn>2</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">15 + 28 + 85 + 72 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li><li><strong>进阶题</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>9</mn><mn>9</mn><mo>+</mo><mn>1</mn><mn>9</mn><mn>9</mn><mo>+</mo><mn>1</mn><mn>9</mn><mn>9</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">199 + 199 + 199 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span> (提示：把 199 看成 200)</li><li><strong>挑战题</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>6</mn><mo>−</mo><mn>4</mn><mn>8</mn><mo>+</mo><mn>7</mn><mn>4</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">126 - 48 + 74 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">7</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li></ol><hr><p><em>总结：巧算的精髓在于“观察”。先看个位，再看整体，找准好朋友，计算不再愁！</em></p>',32)])])}const g=s(l,[["render",r]]);export{x as __pageData,g as default};
